"use strict";
Object.defineProperty(exports, "__esModule", { value: true });
exports.renderFullMarkdown = renderFullMarkdown;
function renderFullMarkdown(data) {
    const { idea, classification, specDoc, selectedTechStack, selectedDesign } = data;
    const now = new Date().toLocaleDateString('en-US', { dateStyle: 'long' });
    let md = `# Blueprint.ai — Product Requirements & Architecture Specification

> **Project Concept**: ${idea.trim()}  
> **Date Generated**: ${now}  
> **Platform**: ${classification.platform}  
> **Domain**: ${classification.domain}  
> **Complexity Tier**: ${classification.complexityTier}

---

## Executive Summary
${classification.summary}

- **Core Problem**: ${classification.coreProblem}
- **Target Audience**: ${classification.targetAudience}
- **Primary Capabilities**: ${classification.keyFeatures.map((f) => `\`${f}\``).join(', ')}

`;
    if (selectedTechStack) {
        md += `---

## Approved Technology Stack (Checkpoint 1)

| Layer | Selected Technology |
|---|---|
| **Frontend** | ${selectedTechStack.frontend} |
| **Backend** | ${selectedTechStack.backend} |
| **Database** | ${selectedTechStack.database} |
| **Styling & UI** | ${selectedTechStack.styling} |
| **Cloud & Deployment** | ${selectedTechStack.deployment} |
${selectedTechStack.notes ? `\n**Architectural Notes**: ${selectedTechStack.notes}\n` : ''}

`;
    }
    md += `---

## Complete Technical Specification

`;
    // Append each section in logical order
    const order = [
        'architecture',
        'requirements',
        'algorithms',
        'dataModel',
        'apiEndpoints',
        'folderStructure',
        'businessLogic',
        'techStack',
        'deployment',
        'security',
        'costEstimate',
        'integrations',
        'testingStrategy',
        'riskAssumptions',
    ];
    for (const sectionId of order) {
        const sec = specDoc.sections[sectionId];
        if (sec && sec.content) {
            md += `### ${sec.title}\n\n${sec.content.trim()}\n\n---\n\n`;
        }
    }
    if (selectedDesign) {
        md += `## Design Direction & System Specification (Checkpoint 2)

### Style Philosophy: ${selectedDesign.name}
${selectedDesign.philosophy}

- **Design System Style**: ${selectedDesign.style.name} (${selectedDesign.style.description})
- **Corner Radius**: \`${selectedDesign.style.cornerRadius}\`
- **Typography Scale**:
  - Headings: **${selectedDesign.typography.headingFont}**
  - Body: **${selectedDesign.typography.bodyFont}**
  - Monospace / Code: **${selectedDesign.typography.monoFont}**
- **Color Palette**:
  - Base Background: \`${selectedDesign.colors.base}\`
  - Elevated Surface: \`${selectedDesign.colors.surface}\`
  - Primary CTA: \`${selectedDesign.colors.primary}\`
  - Secondary Accent: \`${selectedDesign.colors.secondary}\`
  - High-Contrast Text: \`${selectedDesign.colors.textPrimary}\`
- **Layout & Grid System**:
  - Composition Style: **${selectedDesign.layout.style}**
  - Spacing & Density: **${selectedDesign.layout.density}**
  - Grid Topology: **${selectedDesign.layout.gridSystem}** (Max Width: \`${selectedDesign.layout.containerWidth}\`)
- **Iconography**:
  - Style: **${selectedDesign.icons.style}** (${selectedDesign.icons.library}) — ${selectedDesign.icons.description}
- **Accessibility & Contrast**: ${selectedDesign.accessibilityNotes}

`;
    }
    md += `\n*Document generated by Blueprint.ai — AI-powered spec & design generator. Fully stateless BYOK architecture.*\n`;
    return md;
}
